CREATE SEQUENCE IF NOT EXISTS stats_player_seq START WITH 1 INCREMENT BY 100;
CREATE TABLE IF NOT EXISTS stats_player (id BIGINT PRIMARY KEY, match_id VARCHAR(255) NOT NULL, name VARCHAR(255) NOT NULL, team VARCHAR(255) NOT NULL, pts INTEGER, reb INTEGER, ast INTEGER, min VARCHAR(255), fgm INTEGER, fga INTEGER, twopm INTEGER, twopa INTEGER, threepm INTEGER, threepa INTEGER, ftm INTEGER, fta INTEGER, plus_minus INTEGER, offensive_rebounds INTEGER, dr INTEGER, pf INTEGER, st INTEGER, turnovers INTEGER, bs INTEGER, ba INTEGER, tfs INTEGER, source_event_id VARCHAR(255) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uk_stats_player_match_player_team UNIQUE(match_id,name,team));
